$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $PSScriptRoot
$utf8 = [Text.UTF8Encoding]::new($false)
$updates = @(
    @{Dir='values'; Heading='Network and third parties'; Intro='Gameplay works offline. Optional rewarded advertising requires an internet connection. Read the policy before starting.'; Body='Network and third parties\nThe app includes Google Mobile Ads (AdMob) and Google User Messaging Platform (UMP) for optional rewarded advertising and advertising privacy choices. There are no player accounts or real-money purchases. Google may process IP addresses (including approximate location inferred from IP), device and advertising identifiers where available, ad interactions and diagnostic data to deliver ads, prevent fraud and measure performance. Advertising requests are treated as below the age of consent for the whole 13+ audience; this restricts personalization, but does not mean that no data is processed. Debug builds use Google demo ads and earn no advertising revenue. Release ads are disabled until the developer configures production identifiers. The game does not send saved progress or tap history to the developer or advertising SDK. It does not request access to contacts, precise location, camera or microphone. Vibration permission provides touch feedback. Telegram is an external service and handles the messages you choose to send with the recipient. Google data practices: https://policies.google.com/privacy .'; Extra='Advertising rewards and choices\nWatching an ad is optional; ordinary offline income is credited without advertising. The game stores a pending bonus identifier, amount and duration alongside progress to prevent duplicate rewards. The bonus is granted only after the advertising SDK confirms that it was earned. Production ad requests are checked against UMP; when required, Advertising privacy choices are available in Settings. Reading or accepting this policy is not consent to personalized advertising. UMP may store advertising privacy choices on the device. Closing the game prevents further ad requests by the game; it does not delete data already processed by Google. Manage Google advertising choices at https://myadcenter.google.com/ and contact Google about data it processes.'},
    @{Dir='values-ru'; Heading='Сеть и сторонние сервисы'; Intro='Игра работает офлайн. Для добровольной рекламы с наградой нужен интернет. Прочитайте политику перед началом.'; Body='Сеть и сторонние сервисы\nПриложение включает Google Mobile Ads (AdMob) и Google User Messaging Platform (UMP) для добровольной рекламы с наградой и управления рекламной конфиденциальностью. Аккаунтов игроков и покупок за реальные деньги нет. Google может обрабатывать IP-адрес (включая приблизительное местоположение по IP), идентификаторы устройства и рекламы при их доступности, взаимодействия с объявлениями и диагностические сведения для показа рекламы, защиты от мошенничества и измерения эффективности. Для всей аудитории 13+ рекламные запросы помечаются как запросы пользователей младше возраста рекламного согласия: это ограничивает персонализацию, но не означает отсутствия обработки данных. В отладочной сборке используются демонстрационные объявления Google без рекламного дохода. В release показы отключены до настройки разработчиком реальных идентификаторов. Игра не передаёт сохранение и историю нажатий разработчику или рекламному SDK. Доступ к контактам, точной геолокации, камере и микрофону не запрашивается. Вибрация используется для отклика на действия. Telegram — внешний сервис, обрабатывающий отправленные вами сообщения вместе с получателем. Политика Google: https://policies.google.com/privacy .'; Extra='Рекламные награды и выбор\nПросмотр рекламы добровольный; обычный офлайн-доход начисляется без рекламы. Вместе с прогрессом игра хранит идентификатор ожидающего бонуса, сумму и длительность, чтобы исключить повторное начисление. Бонус выдаётся только после подтверждения рекламным SDK. Реальные рекламные запросы проверяются через UMP; если это требуется, в настройках доступен раздел рекламной конфиденциальности. Прочтение или принятие этой политики не означает согласия на персонализированную рекламу. UMP может хранить рекламный выбор на устройстве. Закрытие игры прекращает новые запросы рекламы самой игрой, но не удаляет сведения, уже обработанные Google. Управлять рекламными настройками Google можно на https://myadcenter.google.com/; по данным, обрабатываемым Google, обращайтесь в Google.'},
    @{Dir='values-es'; Heading='Red y terceros'; Intro='El juego funciona sin conexión. Los anuncios opcionales con recompensa requieren internet. Lee la política antes de empezar.'; Body='Red y terceros\nLa aplicación incluye Google Mobile Ads (AdMob) y Google User Messaging Platform (UMP) para anuncios opcionales con recompensa y opciones de privacidad publicitaria. No hay cuentas de jugadores ni compras con dinero real. Google puede tratar direcciones IP (incluida la ubicación aproximada inferida), identificadores del dispositivo y publicitarios cuando estén disponibles, interacciones con anuncios y datos de diagnóstico para mostrar anuncios, prevenir fraude y medir resultados. Para toda la audiencia de 13 años o más, las solicitudes se marcan como inferiores a la edad de consentimiento publicitario; esto restringe la personalización, pero no significa que no se traten datos. Las versiones de depuración usan anuncios de prueba de Google sin ingresos. En release los anuncios están desactivados hasta configurar identificadores de producción. El juego no envía partidas ni historial de pulsaciones al desarrollador o al SDK publicitario. No solicita acceso a contactos, ubicación precisa, cámara o micrófono. La vibración ofrece respuesta táctil. Telegram es un servicio externo que trata los mensajes que envíes junto con el destinatario. Política de Google: https://policies.google.com/privacy .'; Extra='Recompensas y opciones publicitarias\nVer anuncios es opcional; los ingresos normales sin conexión se acreditan sin publicidad. El juego guarda el identificador, importe y duración del bono pendiente con el progreso para evitar recompensas duplicadas. El bono solo se concede tras la confirmación del SDK. Las solicitudes de producción se comprueban mediante UMP; cuando sea necesario, las opciones de privacidad publicitaria aparecen en Ajustes. Leer o aceptar esta política no significa consentir publicidad personalizada. UMP puede guardar opciones publicitarias en el dispositivo. Cerrar el juego detiene nuevas solicitudes publicitarias del juego, pero no borra datos ya tratados por Google. Gestiona las opciones de Google en https://myadcenter.google.com/ y contacta con Google sobre sus datos.'}
)
foreach ($entry in $updates) {
    $path = Join-Path $root "app/src/main/res/$($entry.Dir)/privacy.xml"
    $source = [IO.File]::ReadAllText($path)
    $pattern = [regex]::Escape($entry.Heading) + '\\n.*?(?=\\n\\n)'
    if (![regex]::IsMatch($source, $pattern)) { throw "Policy section missing: $path" }
    $source = [regex]::Replace($source, $pattern, [System.Text.RegularExpressions.MatchEvaluator]{param($match) $entry.Body})
    $source = [regex]::Replace($source, '(<string name="privacy_intro">).*?(</string>)', [System.Text.RegularExpressions.MatchEvaluator]{param($match) $match.Groups[1].Value + $entry.Intro + $match.Groups[2].Value})
    if (!$source.Contains($entry.Extra)) {
        $pattern = '(<string name="privacy_policy_body">.*?)(</string>)'
        $source = [regex]::Replace($source, $pattern, [System.Text.RegularExpressions.MatchEvaluator]{param($match) $match.Groups[1].Value + '\n\n' + $entry.Extra + $match.Groups[2].Value}, 'Singleline')
    }
    [IO.File]::WriteAllText($path, $source, $utf8)
}
& (Join-Path $PSScriptRoot 'Export-PrivacyPolicy.ps1')
